def multi_browserbase_stagehand_session_create(name=None, browserbaseSessionID=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0539000" if __import__("os").path.isdir("./environment_mix/0539000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request log (best-effort; schema not provided)
    def _log(status, workspace_id=None, session_id=None, error=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "multi_browserbase_stagehand_session_create",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id,
            "session_id": session_id,
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if name is not None and not isinstance(name, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "name must be a string"})
        return _err("VALIDATION_ERROR", "name must be a string")
    if browserbaseSessionID is not None and not isinstance(browserbaseSessionID, str):
        _log("error", error={"code": "VALIDATION_ERROR", "message": "browserbaseSessionID must be a string"})
        return _err("VALIDATION_ERROR", "browserbaseSessionID must be a string")

    workspaces = _load("workspaces.json")
    sessions = _load("stagehand_sessions.json")

    # Ambient auth: choose a workspace that can satisfy prerequisites (active, quotas, concurrency)
    def _active_session_count(ws_id):
        active_statuses = {"initializing", "running", "paused", "closing"}
        return sum(1 for s in sessions if s.get("workspace_id") == ws_id and s.get("status") in active_statuses)

    candidate_ws = None
    for ws in workspaces:
        if ws.get("status") != "active":
            continue
        if not isinstance(ws.get("session_concurrency_limit"), int) or ws.get("session_concurrency_limit") < 1:
            continue
        if not isinstance(ws.get("monthly_step_limit"), int) or ws.get("monthly_step_used") is None:
            continue
        if not isinstance(ws.get("monthly_session_minutes_limit"), int) or ws.get("monthly_session_minutes_used") is None:
            continue
        # New session creation checks: monthly limits only when nonzero
        if ws.get("monthly_step_limit", 0) != 0 and ws.get("monthly_step_used", 0) >= ws.get("monthly_step_limit", 0):
            continue
        if ws.get("monthly_session_minutes_limit", 0) != 0 and ws.get("monthly_session_minutes_used", 0) >= ws.get("monthly_session_minutes_limit", 0):
            continue
        if _active_session_count(ws.get("id")) >= ws.get("session_concurrency_limit"):
            continue
        candidate_ws = ws
        break

    # If browserbaseSessionID is provided, attempt resume within some workspace; prefer one where the session exists
    if browserbaseSessionID is not None:
        for ws in workspaces:
            if ws.get("status") != "active":
                continue
            # resume does not create a new session, so it doesn't need a concurrency slot,
            # but it must be in caller workspace; we approximate by choosing a workspace where it exists.
            for s in sessions:
                if (
                    s.get("workspace_id") == ws.get("id")
                    and s.get("mode") == "multi"
                    and s.get("browserbase_session_id") == browserbaseSessionID
                    and s.get("status") in ("running", "paused")
                ):
                    # found resumable session
                    _log("ok", workspace_id=ws.get("id"), session_id=s.get("id"))
                    return {
                        "sessionId": s.get("id"),
                        "id": s.get("id"),
                        "name": s.get("name"),
                        "browserbaseSessionID": s.get("browserbase_session_id"),
                        "status": s.get("status"),
                        "created_at": s.get("created_at"),
                        "updated_at": s.get("updated_at"),
                        "last_activity_at": s.get("last_activity_at"),
                    }

        # If not found anywhere, proceed to create a new session (rule says: otherwise create new row)
        # Need an authorized workspace with capacity.
        if candidate_ws is None:
            _log("error", error={"code": "UNAUTHORIZED", "message": "No active workspace available to create session"})
            return _err("UNAUTHORIZED", "No active workspace available to create session")

    else:
        if candidate_ws is None:
            _log("error", error={"code": "UNAUTHORIZED", "message": "No active workspace available to create session"})
            return _err("UNAUTHORIZED", "No active workspace available to create session")

    ws = candidate_ws

    # Enforce concurrency and monthly limits for creation
    if ws.get("status") != "active":
        _log("error", workspace_id=ws.get("id"), error={"code": "UNAUTHORIZED", "message": "Workspace not active"})
        return _err("UNAUTHORIZED", "Workspace not active")
    if _active_session_count(ws.get("id")) >= ws.get("session_concurrency_limit"):
        _log("error", workspace_id=ws.get("id"), error={"code": "QUOTA_EXCEEDED", "message": "Session concurrency limit exceeded"})
        return _err("QUOTA_EXCEEDED", "Session concurrency limit exceeded")
    if ws.get("monthly_step_limit", 0) != 0 and ws.get("monthly_step_used", 0) >= ws.get("monthly_step_limit", 0):
        _log("error", workspace_id=ws.get("id"), error={"code": "QUOTA_EXCEEDED", "message": "Monthly step limit exceeded"})
        return _err("QUOTA_EXCEEDED", "Monthly step limit exceeded")
    if ws.get("monthly_session_minutes_limit", 0) != 0 and ws.get("monthly_session_minutes_used", 0) >= ws.get("monthly_session_minutes_limit", 0):
        _log("error", workspace_id=ws.get("id"), error={"code": "QUOTA_EXCEEDED", "message": "Monthly session minutes limit exceeded"})
        return _err("QUOTA_EXCEEDED", "Monthly session minutes limit exceeded")

    # Create new multi session with initializing status
    new_id = "shs_" + uuid.uuid4().hex
    # ensure browserbase_session_id uniqueness if provided
    if browserbaseSessionID is not None:
        for s in sessions:
            if s.get("browserbase_session_id") == browserbaseSessionID:
                # uniqueness constraint; but if the existing one isn't resumable, still cannot duplicate
                _log("error", workspace_id=ws.get("id"), error={"code": "CONFLICT", "message": "browserbaseSessionID already in use"})
                return _err("CONFLICT", "browserbaseSessionID already in use")

    row = {
        "id": new_id,
        "workspace_id": ws.get("id"),
        "mode": "multi",
        "name": name,
        "browserbase_session_id": browserbaseSessionID,
        "status": "initializing",
        "current_url": None,
        "started_at": None,
        "closed_at": None,
        "last_activity_at": now,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    sessions.append(row)
    _save("stagehand_sessions.json", sessions)

    # update workspace updated_at for observability
    ws["updated_at"] = now
    _save("workspaces.json", workspaces)

    _log("ok", workspace_id=ws.get("id"), session_id=new_id)
    return {
        "sessionId": row["id"],
        "id": row["id"],
        "name": row.get("name"),
        "browserbaseSessionID": row.get("browserbase_session_id"),
        "status": row.get("status"),
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
        "last_activity_at": row.get("last_activity_at"),
    }

def multi_browserbase_stagehand_session_list(status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0539000" if __import__("os").path.isdir("./environment_mix/0539000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, workspace_id=None, session_id=None, error_code=None, error_message=None):
        files = []
        try:
            files = os.listdir(_DB)
        except Exception:
            files = []
        for fn in ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"]:
            if fn in files:
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "multi_browserbase_stagehand_session_list",
                    "timestamp": _now_iso(),
                    "created_at": _now_iso(),
                    "status": status_s,
                    "workspace_id": workspace_id,
                    "session_id": session_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": int((time.time() - t0) * 1000),
                })
                _save(fn, rows)
                return

    # additionalProperties=false
    if _extra:
        _log("error", error_code="VALIDATION_ERROR", error_message="Unknown fields supplied.")
        return _err("VALIDATION_ERROR", "Unknown fields supplied.", unknown_fields=sorted(list(_extra.keys())))

    allowed_status = {"initializing", "running", "paused", "closing", "closed", "failed"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", error_code="VALIDATION_ERROR", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", error_code="VALIDATION_ERROR", error_message="limit must be between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    allowed_sort = {"created_at", "last_activity_at", "started_at", "updated_at"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("error", error_code="VALIDATION_ERROR", error_message="Invalid sort")
        return _err("VALIDATION_ERROR", "Invalid sort")

    allowed_order = {"asc", "desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _log("error", error_code="VALIDATION_ERROR", error_message="Invalid order")
        return _err("VALIDATION_ERROR", "Invalid order")

    # Cursor: MUST be lenient. Accept any string. If it parses as our cursor, use it; otherwise treat as "start".
    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        # try base64 json cursor; ignore failures
        try:
            raw = cur.encode("utf-8")
            raw += b"==="  # padding
            data = base64.urlsafe_b64decode(raw)
            obj = json.loads(data.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1:
                # offset cursor
                off = obj.get("offset")
                if isinstance(off, int) and off >= 0:
                    # optional fingerprint to avoid obvious mismatch, but don't error
                    return off
        except Exception:
            return None
        return None

    def _encode_cursor(offset):
        payload = {"v": 1, "offset": offset}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    sessions = _load("stagehand_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Only multi sessions visible; per business rule "list returns only ... status in initializing/running/paused/closing"
    visible_statuses = {"initializing", "running", "paused", "closing"}
    rows = [s for s in sessions if s.get("mode") == "multi" and s.get("status") in visible_statuses]

    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    def _sort_key(s):
        v = s.get(sort)
        # None sorts last for asc, first for desc; normalize
        if v is None:
            return ("~" if order == "asc" else "", "")
        return (v, "")

    rows.sort(key=_sort_key, reverse=(order == "desc"))

    offset = _decode_cursor(cursor) or 0
    if offset < 0:
        offset = 0
    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    # response shape: include the fields the business rule calls out, but keep useful extras too
    out = []
    for s in page:
        out.append({
            "id": s.get("id"),
            "name": s.get("name"),
            "status": s.get("status"),
            "browserbaseSessionID": s.get("browserbase_session_id"),
            "browserbase_session_id": s.get("browserbase_session_id"),
            "created_at": s.get("created_at"),
            "last_activity_at": s.get("last_activity_at"),
            "started_at": s.get("started_at"),
            "updated_at": s.get("updated_at"),
            "current_url": s.get("current_url"),
        })

    _log("ok")
    return {
        "data": out,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "cursor": cursor, "sort": sort, "order": order},
    }

def multi_browserbase_stagehand_session_close(sessionId, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0539000" if __import__("os").path.isdir("./environment_mix/0539000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, workspace_id=None, session_id=None, error_code=None, error_message=None):
        try:
            files = os.listdir(_DB)
        except Exception:
            files = []
        for fn in ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"]:
            if fn in files:
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "multi_browserbase_stagehand_session_close",
                    "timestamp": _now(),
                    "created_at": _now(),
                    "status": status_s,
                    "workspace_id": workspace_id,
                    "session_id": session_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": int((time.time() - t0) * 1000),
                })
                _save(fn, rows)
                return

    if _extra:
        _log("error", error_code="VALIDATION_ERROR", error_message="Unknown fields supplied.")
        return _err("VALIDATION_ERROR", "Unknown fields supplied.", unknown_fields=sorted(list(_extra.keys())))
    if not isinstance(sessionId, str) or not sessionId.strip():
        _log("error", error_code="VALIDATION_ERROR", error_message="sessionId must be a non-empty string")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")

    sessions = _load("stagehand_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Lenient resolution: prefer exact id match; if not found and looks like a workspace id, close most-recent active multi session in that workspace.
    target = None
    for s in sessions:
        if s.get("id") == sessionId:
            target = s
            break

    if target is None and sessionId.startswith("bb_ws_"):
        # pick a working combination, not first row; choose newest non-closed multi session in that workspace
        candidates = [s for s in sessions if s.get("workspace_id") == sessionId and s.get("mode") == "multi" and s.get("status") != "closed"]
        if candidates:
            def _k(s):
                return s.get("updated_at") or s.get("created_at") or ""
            candidates.sort(key=_k, reverse=True)
            target = candidates[0]

    if target is None:
        _log("error", session_id=sessionId, error_code="NOT_FOUND", error_message="Session not found")
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    if target.get("mode") != "multi":
        _log("error", session_id=target.get("id"), error_code="UNAUTHORIZED", error_message="Not a multi session")
        return _err("UNAUTHORIZED", "Not a multi session")

    if target.get("status") == "closed":
        _log("ok", workspace_id=target.get("workspace_id"), session_id=target.get("id"))
        return {"data": target}

    # Transition to closing then closed (legal per lifecycle rules for multi close)
    now = _now()
    old = target.get("status")
    # allow any non-closed to go closing; if already closing, proceed to closed
    if old != "closing":
        target["status"] = "closing"
        target["updated_at"] = now

    target["status"] = "closed"
    target["closed_at"] = now
    target["updated_at"] = now
    if target.get("started_at") is None:
        # if it never started, still set started_at when closing/closed per constraint note (best effort)
        target["started_at"] = now
    target["last_activity_at"] = now

    _save("stagehand_sessions.json", sessions)
    _log("ok", workspace_id=target.get("workspace_id"), session_id=target.get("id"))
    return {"data": target}

def multi_browserbase_stagehand_navigate_session(sessionId, url, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0539000" if __import__("os").path.isdir("./environment_mix/0539000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(endpoint, status_s, workspace_id=None, session_id=None, step_id=None, error_code=None, error_message=None):
        try:
            files = set(os.listdir(_DB))
        except Exception:
            files = set()
        for fn in ("request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if fn in files:
                rows = _ensure_list(_load(fn))
                rows.append(
                    {
                        "id": "req_" + uuid.uuid4().hex,
                        "endpoint": endpoint,
                        "timestamp": _now(),
                        "created_at": _now(),
                        "status": status_s,
                        "workspace_id": workspace_id,
                        "session_id": session_id,
                        "step_id": step_id,
                        "error_code": error_code,
                        "error_message": error_message,
                        "latency_ms": int((time.time() - t0) * 1000),
                    }
                )
                _save(fn, rows)
                break

    def _is_nonempty_str(v):
        return isinstance(v, str) and bool(v.strip())

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:26]

    # Validate unknown fields
    if _extra:
        _log("multi_browserbase_stagehand_navigate_session", "error", error_code="VALIDATION_ERROR", error_message="Unknown fields supplied.")
        return _err("VALIDATION_ERROR", "Unknown fields supplied.", unknown_fields=sorted(list(_extra.keys())))

    if not _is_nonempty_str(sessionId):
        _log("multi_browserbase_stagehand_navigate_session", "error", error_code="VALIDATION_ERROR", error_message="sessionId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", sessionId=sessionId)

    if not _is_nonempty_str(url):
        _log("multi_browserbase_stagehand_navigate_session", "error", error_code="VALIDATION_ERROR", error_message="url must be a non-empty string.")
        return _err("VALIDATION_ERROR", "url must be a non-empty string.", url=url)

    sessions = _ensure_list(_load("stagehand_sessions.json"))
    sess = next((s for s in sessions if s.get("id") == sessionId), None)
    if not sess:
        # IMPORTANT: callers sometimes pass a workspace id by mistake; real service still says not found.
        _log("multi_browserbase_stagehand_navigate_session", "error", session_id=sessionId, error_code="NOT_FOUND", error_message="sessionId does not exist")
        return _err("NOT_FOUND", "sessionId does not exist", sessionId=sessionId)

    if sess.get("mode") != "multi":
        _log("multi_browserbase_stagehand_navigate_session", "error", workspace_id=sess.get("workspace_id"), session_id=sessionId, error_code="NOT_FOUND", error_message="sessionId does not exist")
        return _err("NOT_FOUND", "sessionId does not exist", sessionId=sessionId)

    workspace_id = sess.get("workspace_id")
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("multi_browserbase_stagehand_navigate_session", "error", workspace_id=workspace_id, session_id=sessionId, error_code="UNAUTHORIZED", error_message="Workspace not accessible.")
        return _err("UNAUTHORIZED", "Workspace not accessible.", workspaceId=workspace_id)

    if ws.get("status") != "active":
        _log("multi_browserbase_stagehand_navigate_session", "error", workspace_id=workspace_id, session_id=sessionId, error_code="UNAUTHORIZED", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspaceId=workspace_id, status=ws.get("status"))

    # Only operate on running/paused
    if sess.get("status") not in ("running", "paused"):
        _log("multi_browserbase_stagehand_navigate_session", "error", workspace_id=workspace_id, session_id=sessionId, error_code="INVALID_TRANSITION", error_message="Session is not in a runnable state.")
        return _err("INVALID_TRANSITION", "Session is not in a runnable state.", sessionId=sessionId, status=sess.get("status"))

    # Quota: monthly steps
    try:
        step_limit = int(ws.get("monthly_step_limit", 0))
        step_used = int(ws.get("monthly_step_used", 0))
    except Exception:
        step_limit, step_used = 0, 0
    if step_limit != 0 and step_used + 1 > step_limit:
        _log("multi_browserbase_stagehand_navigate_session", "error", workspace_id=workspace_id, session_id=sessionId, error_code="QUOTA_EXCEEDED", error_message="Monthly step quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Monthly step quota exceeded.", monthly_step_limit=step_limit, monthly_step_used=step_used)

    # Create step with atomic per-session sequence (best-effort for single-process local store)
    steps = _ensure_list(_load("session_steps.json"))
    max_seq = 0
    for st in steps:
        if st.get("session_id") == sessionId:
            try:
                seqv = int(st.get("sequence", 0))
                if seqv > max_seq:
                    max_seq = seqv
            except Exception:
                pass
    seq = max_seq + 1

    now = _now()
    step_id = _gen_id("bb_step_")
    step = {
        "id": step_id,
        "session_id": sessionId,
        "sequence": seq,
        "type": "navigate",
        "status": "queued",
        "input_url": url,
        "input_action": None,
        "input_variables": None,
        "input_instruction": None,
        "input_return_action": None,
        "input_screenshot_name": None,
        "output": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    steps.append(step)

