def multi_browserbase_stagehand_session_update(sessionId, name=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0539000" if __import__("os").path.isdir("./environment_mix/0539000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(endpoint, status_s, workspace_id=None, session_id=None, error_code=None, error_message=None):
        try:
            files = set(os.listdir(_DB))
        except Exception:
            files = set()
        for fn in ("request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            if fn in files:
                rows = _ensure_list(_load(fn))
                rows.append(
                    {
                        "id": "req_" + uuid.uuid4().hex,
                        "endpoint": endpoint,
                        "timestamp": _now(),
                        "created_at": _now(),
                        "status": status_s,
                        "workspace_id": workspace_id,
                        "session_id": session_id,
                        "error_code": error_code,
                        "error_message": error_message,
                        "latency_ms": int((time.time() - t0) * 1000),
                    }
                )
                _save(fn, rows)
                break

    def _is_nonempty_str(v):
        return isinstance(v, str) and bool(v.strip())

    def _transition_allowed(cur, nxt):
        allowed = {
            "initializing": {"running", "failed", "closing"},
            "running": {"paused", "closing", "failed"},
            "paused": {"running", "closing", "failed"},
            "closing": {"closed", "failed"},
            "closed": set(),
            "failed": {"closing", "closed"},
        }
        return nxt in allowed.get(cur, set())

    if _extra:
        _log("multi_browserbase_stagehand_session_update", "error", error_code="VALIDATION_ERROR", error_message="Unknown fields supplied.")
        return _err("VALIDATION_ERROR", "Unknown fields supplied.", unknown_fields=sorted(list(_extra.keys())))

    if not _is_nonempty_str(sessionId):
        _log("multi_browserbase_stagehand_session_update", "error", error_code="VALIDATION_ERROR", error_message="sessionId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.", sessionId=sessionId)

    if name is not None and not _is_nonempty_str(name):
        _log("multi_browserbase_stagehand_session_update", "error", session_id=sessionId, error_code="VALIDATION_ERROR", error_message="name must be a non-empty string.")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", name=name)

    if status is not None:
        if not isinstance(status, str) or status not in ("running", "paused", "closing"):
            _log("multi_browserbase_stagehand_session_update", "error", session_id=sessionId, error_code="VALIDATION_ERROR", error_message="Invalid status.")
            return _err("VALIDATION_ERROR", "Invalid status.", status=status)

    sessions = _ensure_list(_load("stagehand_sessions.json"))
    sess = next((s for s in sessions if s.get("id") == sessionId), None)
    if not sess:
        _log("multi_browserbase_stagehand_session_update", "error", session_id=sessionId, error_code="NOT_FOUND", error_message="sessionId does not exist")
        return _err("NOT_FOUND", "sessionId does not exist", sessionId=sessionId)

    if sess.get("mode") != "multi":
        _log("multi_browserbase_stagehand_session_update", "error", workspace_id=sess.get("workspace_id"), session_id=sessionId, error_code="NOT_FOUND", error_message="sessionId does not exist")
        return _err("NOT_FOUND", "sessionId does not exist", sessionId=sessionId)

    workspace_id = sess.get("workspace_id")
    workspaces = _ensure_list(_load("workspaces.json"))
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="UNAUTHORIZED", error_message="Workspace not accessible.")
        return _err("UNAUTHORIZED", "Workspace not accessible.", workspaceId=workspace_id)

    if ws.get("status") != "active":
        _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="UNAUTHORIZED", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspaceId=workspace_id, status=ws.get("status"))

    changed = False
    now = _now()

    if name is not None and name != sess.get("name"):
        sess["name"] = name
        changed = True

    if status is not None and status != sess.get("status"):
        cur = sess.get("status")
        # Tool only supports running/paused/closing. Map from initializing to closing allowed.
        if status == "running":
            # only paused -> running allowed by tool description
            if cur != "paused":
                _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="INVALID_TRANSITION", error_message="Invalid status transition.")
                return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur, to_status=status)
        elif status == "paused":
            if cur != "running":
                _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="INVALID_TRANSITION", error_message="Invalid status transition.")
                return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur, to_status=status)
        elif status == "closing":
            # running|paused|initializing -> closing
            if cur not in ("running", "paused", "initializing"):
                _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="INVALID_TRANSITION", error_message="Invalid status transition.")
                return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur, to_status=status)

        if not _transition_allowed(cur, status):
            _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="INVALID_TRANSITION", error_message="Invalid status transition.")
            return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur, to_status=status)

        sess["status"] = status
        sess["updated_at"] = now
        # If initiating closure, immediately complete to closed as per close business rule behavior
        if status == "closing":
            # closing -> closed
            if not _transition_allowed("closing", "closed"):
                _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="INVALID_TRANSITION", error_message="Cannot transition to closed.")
                return _err("INVALID_TRANSITION", "Cannot transition to closed.", from_status="closing", to_status="closed")
            closed_ts = _now()
            sess["status"] = "closed"
            sess["closed_at"] = closed_ts
            sess["updated_at"] = closed_ts
        changed = True

    if not changed:
        # No success without effect
        _log("multi_browserbase_stagehand_session_update", "error", workspace_id=workspace_id, session_id=sessionId, error_code="CONFLICT", error_message="No changes to apply.")
        return _err("CONFLICT", "No changes to apply.", sessionId=sessionId)

    _save("stagehand_sessions.json", sessions)
    _log("multi_browserbase_stagehand_session_update", "ok", workspace_id=workspace_id, session_id=sessionId)
    return {"session": sess}

def multi_browserbase_stagehand_session_steps_list(sessionId, status=None, type=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0539000" if __import__("os").path.isdir("./environment_mix/0539000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, workspace_id=None, session_id=None, error_code=None, error_message=None):
        try:
            files = os.listdir(_DB)
        except Exception:
            files = []
        for fn in ["request_logs.json", "api_requests.json", "usage_logs.json", "audit_logs.json", "requests.json"]:
            if fn in files:
                rows = _load(fn)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "multi_browserbase_stagehand_session_steps_list",
                    "timestamp": _now(),
                    "created_at": _now(),
                    "status": status_s,
                    "workspace_id": workspace_id,
                    "session_id": session_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": int((time.time() - t0) * 1000),
                })
                _save(fn, rows)
                return

    if _extra:
        _log("error", error_code="VALIDATION_ERROR", error_message="Unknown fields supplied.")
        return _err("VALIDATION_ERROR", "Unknown fields supplied.", unknown_fields=sorted(list(_extra.keys())))
    if not isinstance(sessionId, str) or not sessionId.strip():
        _log("error", error_code="VALIDATION_ERROR", error_message="sessionId must be a non-empty string")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")

    allowed_status = {None, "queued", "running", "succeeded", "failed", "cancelled"}
    if status not in allowed_status:
        _log("error", session_id=sessionId, error_code="VALIDATION_ERROR", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status")
    allowed_type = {None, "navigate", "act", "observe", "extract", "screenshot"}
    if type not in allowed_type:
        _log("error", session_id=sessionId, error_code="VALIDATION_ERROR", error_message="Invalid type")
        return _err("VALIDATION_ERROR", "Invalid type")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", session_id=sessionId, error_code="VALIDATION_ERROR", error_message="limit must be between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    sessions = _load("stagehand_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    steps = _load("session_steps.json")
    if not isinstance(steps, list):
        steps = []

    # resolve session; allow workspace id fallback
    sess = next((s for s in sessions if s.get("id") == sessionId and s.get("mode") == "multi"), None)
    if sess is None and sessionId.startswith("bb_ws_"):
        candidates = [s for s in sessions if s.get("workspace_id") == sessionId and s.get("mode") == "multi"]
        if candidates:
            def _k(s):
                return s.get("updated_at") or s.get("created_at") or ""
            candidates.sort(key=_k, reverse=True)
            sess = candidates[0]

    if sess is None:
        _log("error", session_id=sessionId, error_code="NOT_FOUND", error_message="Session not found")
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    # cursor: lenient. If invalid/unparseable, treat as start.
    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            data = base64.urlsafe_b64decode((cur + "===").encode("utf-8"))
            obj = json.loads(data.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1:
                after = obj.get("after_sequence")
                if isinstance(after, int) and after >= 0:
                    return after
        except Exception:
            return None
        return None

    def _encode_cursor(after_sequence):
        payload = {"v": 1, "sessionId": sess.get("id"), "after_sequence": after_sequence}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    after_seq = _decode_cursor(cursor)
    sid = sess.get("id")

    filtered = [st for st in steps if st.get("session_id") == sid]
    if status is not None:
        filtered = [st for st in filtered if st.get("status") == status]
    if type is not None:
        filtered = [st for st in filtered if st.get("type") == type]

    # order by sequence asc
    filtered.sort(key=lambda r: r.get("sequence") if isinstance(r.get("sequence"), int) else 10**18)

    if after_seq is not None:
        filtered = [st for st in filtered if isinstance(st.get("sequence"), int) and st.get("sequence") > after_seq]

    total = len(filtered)
    page = filtered[:limit]
    has_more = total > len(page)
    next_cursor = _encode_cursor(page[-1].get("sequence")) if has_more and page and isinstance(page[-1].get("sequence"), int) else None

    _log("ok", workspace_id=sess.get("workspace_id"), session_id=sid)
    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
